     "repo": "coya-poc",
     "ko": "코야",
     "note": "인생 시뮬레이션 게임 (개인 실험작)",
     "summary": "어린 시절 이야기가 아예 빈칸으로 나오던 문제부터 고쳤어요. 글을 찍어 낼 틀이 아예 만들어져 있지 않아서, 모든 장면이 빈 문단으로 나오고 있었습니다. 그리고 게임 구조를 크게 바꿨어요. 전에는 여덟 개 탭이 항상 떠 있어서 뭘 해야 할지 알 수 없는 메뉴판 같았는데, 이제 '열여덟 살이 되었을 때' 같은 인생의 단계마다 선택을 하는 방식이 되었습니다. 안전 문제도 두 가지 잡았어요. 누구나 마음대로 갖다 쓸 수 있게 열려 있던 AI 연결 통로를 닫고 잠긴 통로로 다시 붙였고, 이 저장소에 비밀 열쇠를 걸러 내는 설정이 아예 없어서 공개된 곳에 열쇠가 그대로 올라갈 수 있던 상태를 막았습니다. 마지막으로 바뀐 구조에서 결과를 다시 측정했더니, 태어난 환경에 따른 격차가 67%로 오히려 더 벌어졌어요.",
