     "kind": "git",
     "repo": "seneca_maro",
     "ko": "세네카 학습 앱",
     "note": "인적성 · 토익스피킹 · 글쓰기",
     "summary": "토익스피킹 앱에서 사용자가 실제로 겪던 문제들을 몰아서 고쳤어요. 오디오 재생기가 두 개 겹쳐 나와서 하나는 눌러도 소리가 안 나던 것, 채점을 세트가 끝난 뒤가 아니라 진행 중에 하도록 바꾼 것 등입니다. 가장 중요한 건 녹음 삭제예요. 로그인할 때 서명하는 동의서에는 '탈퇴하거나 목적이 끝나면 지체 없이 파기합니다'라고 적혀 있는데, 정작 앱에는 로그아웃 말고 아무 방법이 없었습니다. 지킬 수 없는 약속이었고, 그것도 남의 목소리에 대한 약속이라 그냥 둘 수 없었어요. 그리고 실제 시험에서 15초를 주는 문항에 30초를 주고 있던 것도 실전대로 맞췄습니다 — 두 배 시간으로 연습하면 실전에서 당황하니까요.",
     "bullets": [
      "동의서가 약속한 '녹음 파일 삭제'를 실제로 할 수 있게 구현",
      "실제 시험이 15초인 문항에 30초를 주던 것을 실전대로 수정",
      "겹쳐 나오던 오디오 재생기 · 채점 시점 · 표시 문구 정리",
      "로그인 후 홈으로 떨어지던 것을 원래 가려던 곳으로",
      "이미 서비스 중인 코너를 '준비 중'이라고 안내하던 것 수정"
     ],
