     "note": "학원 학생들이 쓰는 학습 사이트",
     "summary": "새 모의고사(mt17)를 학생들이 실제로 풀 수 있게 열었어요. 빠져 있던 수학 그림 6개를 직접 그려 넣었는데, 옮겨 적은 사람의 설명이 아니라 대학위원회 원본 스캔본을 보면서 하나하나 맞췄습니다. 그 과정에서 이전에 쓰던 자동 환산 방식이 실제 학생 4명의 결과와 견줘 40~120점이나 낮게 매기고 있었다는 걸 확인하고 바로잡았습니다. 밤에는 모의고사 결과를 학생에게 '환산 점수'가 아니라 '정답률(%)'로 보여 주도록 바꿨어요. 환산 점수는 실제 시험 점수처럼 보이는데 우리가 그 정확도를 보장할 수 없어서, 괜히 믿게 만드는 것보다 정직한 숫자를 주는 쪽을 골랐습니다. 그리고 17회 시험을 목요일이 아니라 금요일 시험으로 옮겼어요.",
