     "summary": "어제 '누가 사이트에 들어와서 무엇을 눌렀는지' 기록하는 장치를 새로 넣었는데, 오늘 확인해 보니 한 건도 쌓여 있지 않았어요. 그 사이 169명이 다녀갔는데 기록은 0건이었습니다. 원인을 세 군데로 좁혀 가며 확인했더니, 데이터베이스가 '이런 종류의 기록은 받지 않겠다'는 오래된 규칙 때문에 전부 거절하고 있었어요. 더 나쁜 건 프로그램이 거절당하고도 아무 소리를 내지 않았다는 겁니다. 그래서 하루 동안 아무도 모른 채 데이터가 그냥 버려지고 있었어요. 규칙을 고치고, 앞으로는 거절당하면 티가 나도록 바꿨습니다.",
