     "ko": "세네카 학습 앱",
     "note": "인적성 · 토익스피킹 · 글쓰기",
     "summary": "어제 옆에 짓기 시작한 새 토익 앱을 오늘 처음으로 진짜 서버에 올려 봤어요. 그냥 올린 게 아니라, 올렸을 때 보이면 안 되는 게 보이지는 않는지, 커밋을 여러 개 한꺼번에 올리면 하나가 누락되지 않는지를 일부러 시험해 보고 확인했습니다. 실제로 누락되는 경우를 찾아서 고쳤어요. 그리고 토익 '읽기' 시험은 기본적으로 잠가 뒀습니다 — 아직 난이도가 맞는지 확인이 안 끝나서, 열어 두고 고치는 대신 닫아 두고 고치기로 한 거예요. 카카오 로그인이 가끔 실패하던 것도 고쳤습니다.",
