     "summary": "토익 말하기 앱은 지금까지 잘 재기만 하고 거의 가르치지 않았어요. 녹음하면 등급과 '하나만 고친다면' 한 줄이 나오고, 그다음 안내는 사실상 '다시 연습하세요'뿐이었습니다. 오늘 그 뒤를 채웠어요.\n\n먼저 채점 결과에 '무슨 일이 있었는지'를 붙였습니다. 몇 초 말했고 어디서 멈췄는지 같은, 등급 말고 실제 관찰 내용이에요. 그다음 모범 낭독을 붙였는데, 여기서 중요한 선택을 했습니다 — 1번 파트는 지문을 그대로 읽는 문제라 모범 답안이 곧 지문 자체예요. 그래서 AI가 지어낸 문장을 학생에게 주는 일이 아예 없습니다. 어휘도 마찬가지로, 이미 갖고 있던 지문 250개 안에 토익 필수 단어 287개가 흩어져 있는 걸 찾아냈어요. 새로 만든 게 아니라 원래 있던 걸 꺼낸 겁니다.\n\n답변 틀도 만들었는데, 규칙을 하나 세웠어요 — 틀에는 연결어만 넣고 내용은 절대 안 넣습니다. 통째로 외운 문장을 쓰면 채점에서 오히려 감점되거든요. 그리고 저녁엔 실제 사용자 한 명이 8문항을 다 녹음했는데 8개 전부 채점에 실패한 일이 있었어요(채점 AI 열쇠 문제). 화면엔 '채점하지 못했어요'만 떴는데, 녹음은 멀쩡히 다 올라가 있었습니다. 채점이 실패해도 나머지는 받을 수 있게 고쳤어요.\n\n밤에는 토익 '듣기' 문제도 처음 만들기 시작했습니다. 15문항을 조용히 넣어 뒀어요.",
     "bullets": [
      "채점 결과에 등급 말고 '실제로 무슨 일이 있었는지'를 함께 표시",
      "모범 낭독 100개 추가 — AI가 지어낸 게 아니라 지문 원본 그대로",
      "지문 속에 이미 있던 토익 필수 단어 287개를 찾아 학습에 연결",
      "답변 틀 제작 — 연결어만, 내용은 넣지 않음 (외운 티 나면 감점되니까)",
      "채점이 실패해도 녹음·모범낭독·어휘는 받을 수 있게 (실사용자 8문항 전부 실패한 사고 대응)",
      "토익 듣기 문제 15개 + 성우 4개 억양 오디오 제작 시작",
      "한국 인터넷 자료의 시험 형식 정보가 낡았다는 걸 확인하고 규칙으로 기록"
     ],
