     "summary": "어제 만든 '처방' 기능이 실제로 무슨 말을 하고 있는지 기록으로 남기게 했어요. 언제 무슨 말을 했고 그때 학습자 상태가 어땠는지를 함께 저장합니다.\n\n그리고 저장된 처방을 직접 읽어 봤는데, 네 개 중 두 개가 사람이 실행할 수 없는 지시였어요. '이렇게 하세요'라고 했는데 실제로는 그렇게 할 방법이 없는 종류입니다. 만든 사람이 직접 읽어 보지 않으면 절대 안 걸리는 문제예요.",
