     "ko": "세네카 학습 앱",
     "note": "인적성 · 토익스피킹 · 글쓰기",
     "summary": "토익 결과 화면이 52명 중 47명에게 '지적할 항목이 없어요'라고 답하고 있었어요. 잘해서가 아니라 조언을 만드는 코드가 아예 호출되지 않아서였습니다. 10문항을 푼 학습자가 조언을 0개 받는 상태였어요.\n\n그리고 낭독에서 관찰한 습관을 즉흥 발화 채점에 그대로 갖다 붙이고 있던 것도 찾았습니다. 글을 읽을 때의 버릇과 자유롭게 말할 때의 버릇은 다른데 같은 것으로 취급하고 있었어요. 아직 근거가 부족해 처방할 수 없는 세 가지는 처방하지 않고 관찰만 하도록 남겨 뒀습니다.\n\n대학 에세이 기능도 정식으로 열었고, 인적성 시험은 끝나자마자 바로 오답을 복기할 수 있게 만들었어요.",
