     "kind": "git",
     "repo": "seneca_maro",
     "ko": "세네카 학습 앱",
     "note": "인적성 · 토익스피킹 · 글쓰기",
     "summary": "한 앱에서 찾은 버그를 다른 앱에도 같은 모양으로 있는지 전부 확인했어요. 여섯 가지 종류로 나눠서 세 개 앱을 훑었습니다.\n\n대표적인 것들이에요. 데이터를 못 읽어 왔을 때 '0'이라고 표시해서 마치 아무것도 안 한 것처럼 보이던 것, 시간이 초과돼 다시 시도하면 같은 작업이 두 번 저장되던 것, 한글을 입력하다 엔터를 치면 조합 중인 글자가 그대로 제출되던 것 같은 문제들입니다. 전부 사용자는 조용히 손해를 보는데 화면에는 아무 표시가 없는 종류예요.\n\n그리고 수업 녹음을 받아 필기로 만들고 검증된 학습 카드까지 만들어 주는 기능을 무료로 열었습니다.",
     "bullets": [
      "앱 세 개에서 같은 종류의 버그를 6가지로 분류해 일제 점검",
      "읽기 실패를 '0'으로 표시해 아무것도 안 한 것처럼 보이던 문제",
      "재시도 시 같은 작업이 두 번 저장되던 문제",
      "한글 입력 중 엔터로 미완성 글자가 제출되던 문제",
      "수업 녹음 → 필기 → 학습 카드 기능 무료 공개"
     ],
