     "summary": "검색 사이트가 페이지를 제대로 읽어 갈 수 있도록 주소 체계를 정리했어요. 같은 페이지가 여러 주소로 보이던 걸 하나로 모으고, 새 페이지가 생기면 검색 엔진에 바로 알릴 수 있게 했습니다. 기다리는 대신 알려 주는 방식이에요.\n\n창피한 것도 하나 발견했어요. 대학 에세이 기능의 예시로 올려 둔 글이, 정작 그 제품이 '이렇게 쓰면 안 된다'고 잡아내려는 바로 그런 글이었습니다. 다시 썼어요.\n\n밤에는 인적성 앱에서 사람이 빠져나가는 자리 세 곳을 막았습니다. 인성검사가 로그인부터 요구하던 것, 구글 로그인이 없던 것, 체험 첫 화면 설명이 부담스럽던 것이에요. 그리고 로그인 전에 문제 두 개를 먼저 풀어 볼 수 있게 바꿨습니다.",
