     "note": "인적성 · 토익스피킹 · 글쓰기",
     "summary": "화면을 크게 정리했어요. 첫 화면에 큰 덩어리가 다섯 개 있어서 어디를 봐야 할지 알 수 없었는데, 초점을 하나로 줄였습니다. 자료실도 제목 78개를 그냥 늘어놓는 대신 '어떤 종류가 있는지'부터 보이게 바꿨어요.\n\nAP 시험 준비에도 제대로 된 입구를 만들었습니다. 그전에는 모두가 에세이 쪽으로 먼저 안내되고 있었거든요. 그리고 문제와 자료실이 실제로 연결되도록 이어 붙였어요 — 문제를 풀다 막히면 그 자리에서 관련 자료로 갈 수 있습니다.\n\n오전에는 외부 검토에서 나온 지적 사항을 전부 반영했고, 저장한 글이 유령처럼 옛날 버전으로 되돌아가던 문제의 원인도 찾았어요. 앱이 아니라 데이터베이스 쪽이었습니다.",
