     "summary": "연습시험 11회분을 전부 열고, 어떤 걸 이미 봤는지 알 수 있는 선택 화면을 붙였어요.\n\n그리고 지금까지 내보낸 문제 1,617개의 정답을 전부 다시 검증했습니다. 기존 정답을 보고 확인하면 눈이 끌려가니까, 정답을 가린 채 처음부터 다시 풀어서 대조하는 방식으로 했어요. 그 결과 잘못된 정답 하나를 찾아 고쳤습니다.\n\n직접 숫자를 써 넣는 수학 문제의 채점 허용 범위도 고쳤어요. 정답이 아주 작은 숫자일 때 고정된 허용 범위를 쓰면 맞는 답도 틀렸다고 나오거든요. 정답 크기에 따라 범위가 같이 움직이게 했습니다.",
