     "note": "인적성 · 토익스피킹 · 글쓰기",
     "summary": "AP 과목 11개에 숙제 도움 기능을 열었어요. 학생이 실제로 받은 숙제와 시험 문제를 가져와서 도움을 받을 수 있는 방식입니다. 9개 과목은 모의시험까지 볼 수 있어요.\n\n그리고 마로를 독립 브랜드로 떼어 냈습니다. 주소를 marolab.kr로 옮기고, 코드 곳곳에 박혀 있던 옛 주소를 전부 바꿨어요.\n\nAI 활용 평가도 이어서 넓혔습니다. 인사·마케팅·리서치 같은 직무별로 짧은 과제 묶음을 만들어서, 자기 일과 가까운 것으로 볼 수 있게 했어요.\n\n그 밖에 시험 총점이 '푼 문제'가 아니라 '전체 영역' 기준으로 계산되도록 고쳤고, 닫았던 숙제 페이지를 다시 열 수 있게 했습니다.",
