     "summary": "AI 활용 평가 과제를 실제 채용 공고에 나오는 업무를 보고 다시 만들었어요. 급여 계산 검증, 세금계산서 대사 같은 진짜 사무 업무입니다. 상상해서 만든 과제가 아니라 실제로 사람들이 하는 일에서 가져왔어요.\n\n그러다 채점 방식 자체가 잘못됐다는 걸 발견했습니다. 답안에 특정 단어가 들어 있으면 맞다고 처리하고 있었는데, 일부러 틀린 답을 넣어 시험해 보니 7개 중 5개를 잘못 채점했어요. 그 방식을 통째로 버리고 다시 만들었습니다.\n\n토익 쪽에서는 오래된 녹음 흐름이 서버에 빈 기록을 계속 만들어 내던 것도 막았어요. 그동안 학생이 다시 녹음한 것을 '중간에 그만둔 것'으로 잘못 세고 있었습니다.",
